<span class="line"><span style="color:#24292E;">({}).hasOwnProperty.</span><span style="color:#6F42C1;">call</span><span style="color:#24292E;">(foo, </span><span style="color:#032F62;">&#39;bar&#39;</span><span style="color:#24292E;">); </span><span style="color:#6A737D;">// true</span></span>
